#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4
cd "$(dirname "${BASH_SOURCE[0]}")/.."
umask 077

for tool in age age-plugin-fido2-hmac nix openssl cmp; do
  command -v "$tool" >/dev/null || {
    printf 'Missing command: %s. Run from your existing devshell.\n' "$tool" >&2
    exit 1
  }
done

MASTER_IDENTITY="$PWD/secrets/security-key-identity.pub"
RECIPIENT=$(awk '/^# public key: / { print $4 }' "$MASTER_IDENTITY")
[[ "$RECIPIENT" == age1* && "$RECIPIENT" != *$'\n'* ]] || {
  printf 'Expected one public recipient in %s\n' "$MASTER_IDENTITY" >&2
  exit 1
}

flake_source() {
  nix eval --impure --raw --expr '
    builtins.path {
      path = ./.;
      name = "nix-config-migration";
      filter = path: type:
        !(builtins.elem (builtins.baseNameOf path) [
          ".git" ".direnv" ".terraform" ".DS_Store" "result"
          "terraform.tfstate" "terraform.tfstate.backup"
        ]);
    }
  '
}

stage "Select the existing decryption identity"
say "The FIDO2 identity is ready. Select the software SSH key used for your existing secrets."
ask OLD_IDENTITY "SSH private-key path [Enter for $HOME/.ssh/id_ed25519]:"
OLD_IDENTITY="${OLD_IDENTITY:-$HOME/.ssh/id_ed25519}"
OLD_IDENTITY="${OLD_IDENTITY/#\~\//$HOME/}"
[[ -r "$OLD_IDENTITY" ]] || {
  printf '%sCannot read identity: %s%s\n' "$RED" "$OLD_IDENTITY" "$RESET" >&2
  exit 1
}
say "Old key: $OLD_IDENTITY"
say "New public recipient: $RECIPIENT"
say "The existing state passphrase and every other secret value will be preserved."
pause

stage "Re-encrypt and verify repository secrets"
MIGRATION_DIR=$(mktemp -d "${TMPDIR:-/tmp}/agenix-rekey-migration.XXXXXX")
mkdir "$MIGRATION_DIR/originals" "$MIGRATION_DIR/updated"
completed=false
cleanup() {
  local status=$?
  if [[ "$completed" == true ]]; then
    rm -rf "$MIGRATION_DIR"
  else
    printf '\nMigration stopped. Encrypted originals and staging files are in:\n%s\n' "$MIGRATION_DIR" >&2
  fi
  exit "$status"
}
trap cleanup EXIT

sources=(secrets/*.age)
say "Preparing ${#sources[@]} secrets. PIN/touch prompts are expected for each verification."
say "Only encrypted files are written to the staging directory."
confirm "Re-encrypt these secrets to the Security Key?" || exit 1

for source in "${sources[@]}"; do
  name=$(basename "$source")
  original="$MIGRATION_DIR/originals/$name"
  updated="$MIGRATION_DIR/updated/$name"
  cp "$source" "$original"
  say "Preparing $name"

  original_hash=$(age -d -i "$OLD_IDENTITY" -i "$MASTER_IDENTITY" "$original" | openssl dgst -sha256)
  age -d -i "$OLD_IDENTITY" -i "$MASTER_IDENTITY" "$original" |
    age -r "$RECIPIENT" -o "$updated"
  updated_hash=$(age -d -i "$MASTER_IDENTITY" "$updated" | openssl dgst -sha256)
  [[ "$original_hash" == "$updated_hash" ]] || {
    printf 'Plaintext verification failed for %s; originals have not been replaced.\n' "$name" >&2
    exit 1
  }
done

for source in "${sources[@]}"; do
  cmp -s "$source" "$MIGRATION_DIR/originals/$(basename "$source")" || {
    printf '%s changed during migration; stopping before replacement.\n' "$source" >&2
    exit 1
  }
done

confirm "All plaintext hashes match. Replace the repository ciphertexts?" || exit 1
for source in "${sources[@]}"; do
  mv "$MIGRATION_DIR/updated/$(basename "$source")" "$source"
done
say "Repository secrets are now encrypted solely to the Security Key recipient."
pause

stage "Generate the host-encrypted copies"
SYSTEM=$(nix eval --impure --raw --expr builtins.currentSystem)
FLAKE_SOURCE=$(flake_source)
say "Rekeying for the three NixOS hosts. OpenTofu secrets remain master-only."
AGENIX_REKEY_ADD_TO_GIT=false nix run "$FLAKE_SOURCE#agenix-rekey.$SYSTEM.rekey"
say "Encrypted host copies are in secrets/rekeyed/. Nothing has been staged or deployed."
pause

stage "Verify host evaluation, devshell and state decryption"
FLAKE_SOURCE=$(flake_source)
nix eval --json "$FLAKE_SOURCE#nixosConfigurations" \
  --apply 'hosts: builtins.mapAttrs (_: host: host.config.system.build.toplevel.drvPath) hosts'
nix eval --raw "$FLAKE_SOURCE#darwinConfigurations.macbook-m3-pro.system.drvPath"
printf '\n'

say "Entering the updated devshell. Expect PIN/touch prompts for the three OpenTofu secrets."
say "OpenTofu init will install the locked providers; state pull only reads and decrypts state."
# shellcheck disable=SC2016
nix develop "$FLAKE_SOURCE#default" --command bash -euc '
  test -n "$TF_VAR_hcloud_token"
  test -n "$TF_VAR_cloudflare_api_token"
  test -n "$TF_VAR_passphrase"
  tofu -chdir=terraform init -input=false -lockfile=readonly
  tofu -chdir=terraform state pull >/dev/null
  printf "Devshell variables and existing state decryption verified.\n"
'

completed=true
finish
say "Review git diff, then add the new Nix files, public split identity and secrets/rekeyed/ to Git."
say "Reload your regular devshell after adding those files so Git-based flake evaluation can see them."
say "Subsequent secret edits use: agenix edit secrets/<name>.age, followed by agenix rekey."
say "No systems have been deployed, no resources applied and no state-encryption key changed."
